questions.modelAnswer:
var ga = new GlideAggregate('incident');
ga.addQuery('active', true);
ga.addQuery('priority', 1);
ga.addAggregate('COUNT');
ga.query();
var count = 0;
if (ga.next()) {
    count = ga.getAggregate('COUNT');
}

GlideAggregate is a distinct API built specifically for COUNT/SUM/AVG/MIN/MAX. Internally it translates to a database-level aggregate query (conceptually a SQL COUNT(*) with the same WHERE clause) rather than a row-returning SELECT, so the database itself does the counting and only a single aggregate number crosses back into the script. The original GlideRecord loop, by contrast, has to materialize every matching row's full field data just to let the script throw almost all of it away one increment at a time — the database and the application server both do far more work than the task actually needs.

var VendorContractLookup = Class.create();
VendorContractLookup.prototype = Object.extendsObject(AbstractAjaxProcessor, {

    isContractActive: function() {
        var vendorId = this.getParameter('sysparm_vendor_id');
        return this._lookupActiveFlag(vendorId) ? 'true' : 'false';
    },

    _lookupActiveFlag: function(vendorId) {
        var gr = new GlideRecord('core_company');
        gr.addQuery('sys_id', vendorId);
        gr.query();
        if (gr.next()) {
            return gr.getValue('u_contract_active') == 'true';
        }
        return false;
    },

    type: 'VendorContractLookup'
});

Beyond the script itself, two platform-level settings must be correct: the Script Include record's "Client callable" checkbox must be checked (false by default, specifically to keep server-side utilities from being exposed accidentally), and the class must extend AbstractAjaxProcessor, ServiceNow's required base class wiring any Script Include into the GlideAjax request/response plumbing — without it, the Script Include cannot be a GlideAjax target no matter how 'Client callable' is set. The underscore-prefixed _lookupActiveFlag is never reachable from the client regardless of the Client callable setting, because the underscore convention is enforced by the platform as a real security boundary, not just a naming style.

var ChangeRiskCalculator = Class.create();
ChangeRiskCalculator.prototype = {
    initialize: function() {
        this.riskThreshold = 3; // 1 = Very High ... matches the Change risk scale used here
    },

    isHighRisk: function(gr) {
        var risk = parseInt(gr.getValue('risk'), 10);
        return risk <= this.riskThreshold;
    },

    type: 'ChangeRiskCalculator'
};

The type property must be a string that exactly matches the class's actual name, and it's a required ServiceNow convention, not decoration — the platform's internal reflection uses it to correctly identify the class, including in error logging and anywhere else the platform needs to know what kind of object it's holding. If ChangeRiskCalculator is renamed to ChangeRiskEvaluator everywhere it's declared and called, but the type string is left as the old 'ChangeRiskCalculator', the code still runs without throwing an error — JavaScript doesn't enforce this — but any platform-level behavior that relies on reading type to identify the object correctly (diagnostic logging, certain reflection-based platform features) now reports or reasons about the wrong class name, which is a quiet, easy-to-miss bug that a rename review can catch only by explicitly checking for it.

(function process(/*RESTAPIRequest*/ request, /*RESTAPIResponse*/ response) {

    var assetTag = request.pathParams.assetTag;

    var gr = new GlideRecord('x_acme_fleet_vehicle');
    gr.addQuery('asset_tag', assetTag);
    gr.query();

    if (!gr.next()) {
        response.setStatus(404);
        response.setBody({ error: 'No vehicle found with asset tag ' + assetTag });
        return;
    }

    response.setBody({
        make: gr.getValue('make'),
        model: gr.getValue('model'),
        assigned_driver: gr.assigned_driver.getDisplayValue()
    });

})(request, response);

Because {assetTag} is a placeholder segment in the resource's relative path, ServiceNow parses it automatically into request.pathParams.assetTag. If the same value arrived instead as part of the query string (e.g. /vehicle?assetTag=FL-4471), it would be read from request.queryParams.assetTag instead — same request object, different property, because path parameters identify *which* resource the request is about, while query parameters express filters or options on top of a resource that's already identified some other way.

function callWithBackoff(maxRetries) {
    var backoffMs = 1000;
    var attempt = 0;

    while (attempt <= maxRetries) {
        var request = new sn_ws.RESTMessageV2('PartnerAPI', 'getPricing');
        var response = request.execute();
        var statusCode = response.getStatusCode();

        if (statusCode == 200) {
            return response;
        }

        attempt++;
        if (attempt <= maxRetries) {
            gs.sleep(backoffMs);
            backoffMs = backoffMs * 2; // 1s, 2s, 4s, 8s
        }
    }
    return null;
}

Retrying immediately, in a tight loop, makes a struggling system worse because every caller hitting a 503 fires its next attempt right away too, so the load that caused the overload in the first place never actually decreases — it stays constant or spikes further exactly while the partner system most needs breathing room to recover. Exponential backoff fixes this two ways at once: each individual caller waits progressively longer, giving the partner's system real time to recover, and because different callers started their waits at slightly different moments, their retries naturally spread out over time instead of synchronizing into another thundering-herd spike.

