// BEFORE
(function executeRule(current, previous) {
    current.u_priority_score = calculateScore(current);
    current.update(); // re-triggers business rules on this table
})(current, previous);

questions.modelAnswer:
(function executeRule(current, previous) {
    var newScore = calculateScore(current);

    if (current.u_priority_score == newScore) {
        return; // already correct -- nothing to save, nothing to re-trigger
    }

    current.u_priority_score = newScore;
    current.setWorkflow(false); // this save won't re-fire business rules on this table
    current.update();
})(current, previous);

The two fixes are an idempotent guard (skip the save entirely once the computed value already matches the stored value) and current.setWorkflow(false) immediately before the save (telling the platform this particular update shouldn't re-trigger business rules, workflows, or flows on the table). The shrinking-duration pattern in the original debug output was the signature of a converging recursive trigger: each current.update() call is itself a fresh save, which makes every business rule configured to run on update — including this same one — eligible to fire again; the score recalculates, changes less each time as it approaches its final correct value, and the loop only stops once the recalculated value finally stops changing and ServiceNow's recursion cap is reached. The decreasing durations weren't six independent slow runs — they were one real problem, re-triggering itself and gradually converging to a stop.

