function onSubmit() {
    var vendorId = g_form.getValue('vendor');
    if (!vendorId) {
        return true;
    }

    var ga = new GlideAjax('VendorContractLookup');
    ga.addParam('sysparm_name', 'isContractActive');
    ga.addParam('sysparm_vendor_id', vendorId);
    ga.getXMLWait(); // synchronous for a submit-blocking check
    var isActive = ga.getAnswer();

    if (isActive !== 'true') {
        g_form.addErrorMessage('This vendor\'s contract is not currently active. Submission blocked.');
        return false;
    }
    return true;
}
